const bmo=months.reduce((a,m)=>!a||m.p>a.p?m:a,null),wmo=months.reduce((a,m)=>!a||m.p<a.p?m:a,null);let stk=0;if(days.length){const up=L.p>=0;for(let i=days.length-1;i>=0&&(days[i].p>=0)==up;i--)stk++}
