 let W=JSON.parse(JSON.stringify(D)),tab=(!D.days.length&&!D.holdings.length)?'setup':'days',all=false,msg=API?'Live saving is on. Changes go straight to your site.':'Changes save in this browser only. See Publish to update the live site.',st=0,dq='',showHelp=false,pvp='index',hist=[];W.ov=W.ov||{};W.flows=W.flows||[];W.updates=W.updates||[];W.faq=W.faq||[];W.orders=W.orders||[];W.trades=W.trades||[];W.bench=W.bench||{name:'',months:[]};
